#!/usr/bin/env python3
"""本地目录备份与恢复最小工具（快照版本 1）。

用法:
    python backup.py backup SOURCE SNAPSHOT
    python backup.py restore SNAPSHOT DEST [--file PATH]...

--file 可重复指定，只从快照恢复清单中逐字匹配的相对路径；
未提供 --file 时恢复清单中的全部文件。

快照目录结构:
    SNAPSHOT/data/...        保留相对目录结构的文件原始字节
    SNAPSHOT/manifest.json   UTF-8 JSON 清单

任何可预先判定的错误都在创建目标目录之前检出；所有失败向标准错误
输出原因并以退出码 2 结束，成功时退出码为 0。
"""

import argparse
import json
import os
import shutil
import stat
import sys
from pathlib import Path

MANIFEST_NAME = "manifest.json"
DATA_DIRNAME = "data"
FORMAT_VERSION = 1
COPY_BUFFER_SIZE = 1024 * 1024

EXIT_OK = 0
EXIT_ERROR = 2


class BackupError(Exception):
    """可向用户报告的预期错误。"""


def fail(message):
    raise BackupError(message)


def _is_within(child, parent):
    """判断已解析的路径 child 是否位于 parent 之内（含相等）。"""
    try:
        child.relative_to(parent)
        return True
    except ValueError:
        return False


def _split_relpath(rel):
    """校验并拆分清单中的相对路径，返回路径分量；非法则失败。"""
    if not isinstance(rel, str) or rel == "":
        fail("清单中的路径必须是非空字符串")
    if rel.startswith("/"):
        fail(f"清单包含绝对路径: {rel}")
    parts = rel.split("/")
    for part in parts:
        if part in ("", ".", ".."):
            if part == "..":
                fail(f"清单包含上级目录分量: {rel}")
            fail(f"清单包含不规范的路径: {rel}")
    return parts


def _validate_within(base_resolved, parts, label, raw):
    """确认 base/parts 解析后仍位于 base 之内（防御符号链接逃逸）。"""
    candidate = base_resolved.joinpath(*parts)
    # strict=False：末端文件可能尚不存在，但其已存在的父级会被真实解析。
    resolved = candidate.resolve(strict=False)
    if not _is_within(resolved, base_resolved):
        fail(f"清单路径解析后越出{label}: {raw}")
    return resolved


def _collect_source_files(source):
    """递归收集源目录中的普通文件，返回使用斜杠分隔的相对路径列表。"""
    collected = []

    def scan(dir_path, rel_prefix):
        try:
            entries = list(os.scandir(dir_path))
        except OSError as exc:
            fail(f"无法读取源目录 {dir_path}: {exc}")
        for entry in entries:
            rel = f"{rel_prefix}{entry.name}" if rel_prefix else entry.name
            # is_symlink 基于 lstat，不跟随符号链接。
            if entry.is_symlink():
                fail(f"源目录中包含符号链接: {rel}")
            try:
                st = entry.stat(follow_symlinks=False)
            except OSError as exc:
                fail(f"无法读取源条目 {rel}: {exc}")
            mode = st.st_mode
            if stat.S_ISDIR(mode):
                scan(entry.path, rel + "/")
            elif stat.S_ISREG(mode):
                collected.append(rel)
            else:
                fail(f"源目录中包含非普通文件: {rel}")

    scan(str(source), "")
    collected.sort()
    return collected


def _copy_bytes(src_path, dst_path):
    """逐字节复制文件内容，不保留或依赖源文件之外的任何状态。"""
    with open(src_path, "rb") as src_f:
        with open(dst_path, "wb") as dst_f:
            shutil.copyfileobj(src_f, dst_f, length=COPY_BUFFER_SIZE)


def _remove_tree(path):
    shutil.rmtree(path, ignore_errors=True)


def cmd_backup(source_arg, snapshot_arg):
    source = Path(source_arg)
    snapshot = Path(snapshot_arg)

    # ---- 校验源目录（此时绝不创建任何目标）----
    try:
        root_st = os.lstat(source)
    except OSError:
        fail(f"源目录不存在: {source_arg}")
    if stat.S_ISLNK(root_st.st_mode):
        fail(f"源目录自身是符号链接: {source_arg}")
    if not stat.S_ISDIR(root_st.st_mode):
        fail(f"源路径不是目录: {source_arg}")

    try:
        source_resolved = source.resolve(strict=True)
    except OSError as exc:
        fail(f"无法解析源目录: {exc}")

    # ---- 校验快照路径 ----
    if os.path.lexists(snapshot):
        fail(f"快照路径已存在，拒绝覆盖: {snapshot_arg}")
    snapshot_resolved = snapshot.resolve(strict=False)
    if _is_within(snapshot_resolved, source_resolved):
        fail("快照目录不得位于源目录内")

    # ---- 完整遍历源目录，确认全部为普通文件/目录 ----
    rel_paths = _collect_source_files(source_resolved)

    # ---- 所有预先可判定的检查通过后，才创建快照目录 ----
    created = False
    try:
        os.mkdir(snapshot)
        created = True
        data_dir = snapshot / DATA_DIRNAME
        os.mkdir(data_dir)

        for rel in rel_paths:
            parts = rel.split("/")
            src_file = source_resolved.joinpath(*parts)
            dst_file = data_dir.joinpath(*parts)
            os.makedirs(dst_file.parent, exist_ok=True)
            try:
                _copy_bytes(src_file, dst_file)
            except OSError as exc:
                fail(f"复制文件失败 {rel}: {exc}")

        manifest = {
            "version": FORMAT_VERSION,
            "files": [{"path": rel} for rel in rel_paths],
        }
        manifest_tmp = snapshot / (MANIFEST_NAME + ".tmp")
        try:
            with open(manifest_tmp, "w", encoding="utf-8") as f:
                json.dump(manifest, f, ensure_ascii=False, indent=2)
                f.write("\n")
            os.replace(manifest_tmp, snapshot / MANIFEST_NAME)
        except OSError as exc:
            fail(f"写入清单失败: {exc}")
    except BaseException:
        if created:
            _remove_tree(snapshot)
        raise

    print(f"已创建快照目录: {snapshot.resolve()}")
    print(f"已备份文件数: {len(rel_paths)}")
    return EXIT_OK


def _load_manifest(snapshot):
    """读取并严格校验快照清单，返回 (清单条目列表, data 真实路径)。"""
    try:
        snap_st = os.lstat(snapshot)
    except OSError:
        fail(f"快照目录不存在: {snapshot}")
    if stat.S_ISLNK(snap_st.st_mode):
        fail(f"快照目录自身是符号链接: {snapshot}")
    if not stat.S_ISDIR(snap_st.st_mode):
        fail(f"快照路径不是目录: {snapshot}")

    snapshot_resolved = snapshot.resolve(strict=True)
    data_dir = snapshot_resolved / DATA_DIRNAME
    try:
        data_st = os.lstat(data_dir)
    except OSError:
        fail(f"快照数据目录缺失: {data_dir}")
    if stat.S_ISLNK(data_st.st_mode) or not stat.S_ISDIR(data_st.st_mode):
        fail("快照数据目录不是普通目录")

    manifest_path = snapshot / MANIFEST_NAME
    try:
        manifest_st = os.lstat(manifest_path)
    except OSError:
        fail(f"快照清单缺失: {manifest_path}")
    if stat.S_ISLNK(manifest_st.st_mode):
        fail("快照清单是符号链接")
    if not stat.S_ISREG(manifest_st.st_mode):
        fail("快照清单不是普通文件")

    try:
        with open(manifest_path, "rb") as f:
            raw = f.read()
        doc = json.loads(raw.decode("utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        fail(f"快照清单无法读取或 JSON 损坏: {exc}")

    if not isinstance(doc, dict):
        fail("清单顶层必须是 JSON 对象")

    version = doc.get("version")
    # bool 是 int 的子类，需显式排除。
    if not isinstance(version, int) or isinstance(version, bool):
        fail("清单 version 字段类型不符（必须为整数）")
    if version != FORMAT_VERSION:
        fail(f"不支持的清单版本: {version}")

    files = doc.get("files")
    if not isinstance(files, list):
        fail("清单 files 字段类型不符（必须为数组）")

    seen = set()
    entries = []
    for index, item in enumerate(files):
        if not isinstance(item, dict):
            fail(f"清单第 {index} 项类型不符（必须为对象）")
        rel = item.get("path")
        parts = _split_relpath(rel)
        normalized = "/".join(parts)
        if normalized in seen:
            fail(f"清单包含重复文件路径: {normalized}")
        seen.add(normalized)

        # 字面路径用于检查条目本身（lstat 不跟随末端符号链接）。
        data_file = data_dir.joinpath(*parts)
        # 解析路径用于越界检查（会跟随末端及父级符号链接）。
        resolved = data_file.resolve(strict=False)
        if not _is_within(resolved, data_dir):
            fail(f"清单路径解析后越出数据目录: {normalized}")
        try:
            fst = os.lstat(data_file)
        except OSError:
            fail(f"清单引用的数据缺失: {normalized}")
        if stat.S_ISLNK(fst.st_mode):
            fail(f"清单引用的数据是符号链接: {normalized}")
        if not stat.S_ISREG(fst.st_mode):
            fail(f"清单引用的数据不是普通文件: {normalized}")

        entries.append((normalized, parts, data_file))

    return snapshot_resolved, data_dir, entries


def _validate_file_selection(selections):
    """校验 --file 选择值，返回按输入顺序去重后的列表；非法则失败。

    选择值与清单 path 逐字精确匹配：仅拒绝绝对路径与空、.、.. 分量，
    不做大小写转换、路径归一化、通配符匹配或目录展开。
    """
    seen = set()
    selected = []
    for sel in selections:
        if sel == "":
            fail("--file 选择不能为空字符串")
        if sel.startswith("/"):
            fail(f"--file 选择不能是绝对路径: {sel}")
        for part in sel.split("/"):
            if part in ("", ".", ".."):
                fail(f"--file 选择包含无效路径分量: {sel}")
        if sel not in seen:
            seen.add(sel)
            selected.append(sel)
    return selected


def cmd_restore(snapshot_arg, dest_arg, file_selections=None):
    snapshot = Path(snapshot_arg)
    dest = Path(dest_arg)

    # ---- 校验 --file 选择值的形态（不创建任何目标）----
    selected = _validate_file_selection(file_selections or [])

    # ---- 读取并完整校验清单及其引用的数据（不创建任何目标）----
    # 清单校验始终针对整个快照，与是否选择子集无关。
    snapshot_resolved, _, entries = _load_manifest(snapshot)

    # ---- 校验选择的路径确实列入清单（逐字精确匹配）----
    if selected:
        by_path = {normalized: (parts, data_file)
                   for normalized, parts, data_file in entries}
        chosen = []
        for sel in selected:
            entry = by_path.get(sel)
            if entry is None:
                fail(f"选择的路径未在快照清单中: {sel}")
            chosen.append((sel, entry[0], entry[1]))
        entries = chosen

    # ---- 校验恢复目标路径 ----
    if os.path.lexists(dest):
        fail(f"恢复目标已存在，拒绝覆盖: {dest_arg}")
    dest_resolved = dest.resolve(strict=False)
    if _is_within(dest_resolved, snapshot_resolved):
        fail("恢复目录不得位于快照目录内")

    # 解析后不得越出恢复目录。
    for normalized, parts, _ in entries:
        _validate_within(dest_resolved, parts, "恢复目录", normalized)

    # ---- 所有预先可判定的检查通过后，才创建恢复目录 ----
    created = False
    try:
        os.mkdir(dest)
        created = True
        for normalized, parts, data_file in entries:
            dst_file = dest_resolved.joinpath(*parts)
            os.makedirs(dst_file.parent, exist_ok=True)
            try:
                _copy_bytes(data_file, dst_file)
            except OSError as exc:
                fail(f"恢复文件失败 {normalized}: {exc}")
    except BaseException:
        if created:
            _remove_tree(dest)
        raise

    print(f"已创建恢复目录: {dest.resolve()}")
    print(f"已恢复文件数: {len(entries)}")
    return EXIT_OK


def build_parser():
    parser = argparse.ArgumentParser(
        prog="backup.py",
        description="本地目录备份与恢复最小工具",
    )
    subparsers = parser.add_subparsers(dest="command")

    p_backup = subparsers.add_parser(
        "backup", help="备份源目录到新建的快照目录"
    )
    p_backup.add_argument("source")
    p_backup.add_argument("snapshot")

    p_restore = subparsers.add_parser(
        "restore", help="将快照恢复到新建的目标目录"
    )
    p_restore.add_argument("snapshot")
    p_restore.add_argument("dest")
    p_restore.add_argument(
        "--file",
        dest="files",
        action="append",
        metavar="PATH",
        help="只恢复清单中该相对路径对应的文件，可重复指定；"
             "缺省时恢复全部文件",
    )

    return parser


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)

    if args.command == "backup":
        action = lambda: cmd_backup(args.source, args.snapshot)
    elif args.command == "restore":
        action = lambda: cmd_restore(args.snapshot, args.dest, args.files)
    else:
        parser.print_usage(sys.stderr)
        print("错误: 必须指定 backup 或 restore 命令", file=sys.stderr)
        return EXIT_ERROR

    try:
        return action()
    except BackupError as exc:
        print(f"错误: {exc}", file=sys.stderr)
        return EXIT_ERROR
    except OSError as exc:
        print(f"错误: 文件读写失败: {exc}", file=sys.stderr)
        return EXIT_ERROR


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""restore 在写入前对无效快照整体拒绝的可执行回归测试。

验收方式严格走 README 公开命令：

    python backup.py restore SNAPSHOT DEST

只观察退出码、标准输出、标准错误与文件结果，不调用任何内部校验函数。
仅依赖 Python 3 标准库；全部快照与目录在临时目录中运行时准备，
用例结束自动清理，不读写用户现有目录。
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
BACKUP_SCRIPT = ROOT / "backup.py"

# 强制子进程按 UTF-8 输出，断言不依赖运行环境的区域设置。
CHILD_ENV = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")

# 正常快照中的两个文件：文本文件与含零字节（0x00）的二进制文件。
VALID_FILES = {
    "note.txt": "笔记内容\n第二行\n".encode("utf-8"),
    "嵌套 目录/二进制 文件.bin": bytes(range(256)),
}

# 拒绝用例清单中放在问题条目之前的有效文件，用于证明后续条目失败时
# 先前文件也不会被写入恢复目标。
GOOD_FILE = "good.txt"
GOOD_BYTES = b"previously valid file\n"

# 成功摘要的公开输出标记（README：成功时打印目标绝对路径与文件数）。
SUMMARY_MARKERS = ("已创建恢复目录", "已恢复文件数")
ERROR_PREFIX = "错误"


def run_cmd(argv):
    """通过公开命令行执行 backup.py，返回 CompletedProcess。"""
    return subprocess.run(
        [sys.executable, str(BACKUP_SCRIPT), *argv],
        cwd=str(ROOT),
        env=CHILD_ENV,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )


def write_files(base, files):
    """在 base 下按 ``相对POSIX路径 -> 字节`` 写入小文件。"""
    base = Path(base)
    for rel, data in files.items():
        path = base / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)


def build_snapshot(work, files):
    """用公开 backup 命令从运行时准备的源目录生成版本 1 快照。"""
    source = Path(work) / "source"
    snapshot = Path(work) / "snapshot"
    write_files(source, files)
    proc = run_cmd(["backup", str(source), str(snapshot)])
    if proc.returncode != 0 or not snapshot.is_dir():
        raise RuntimeError(
            "测试夹具：基线快照创建失败\n"
            f"exit={proc.returncode}\nstdout={proc.stdout!r}\nstderr={proc.stderr!r}"
        )
    return snapshot


def write_manifest(snapshot, doc):
    (Path(snapshot) / "manifest.json").write_text(
        json.dumps(doc, ensure_ascii=False), encoding="utf-8"
    )


def write_raw_manifest(snapshot, raw):
    (Path(snapshot) / "manifest.json").write_bytes(raw)


def snapshot_tree(root):
    """递归记录目录树：相对路径 -> (类型, 字节或链接目标)，与遍历顺序无关。"""
    root = Path(root)
    tree = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        filenames.sort()
        rel_dir = Path(dirpath).relative_to(root)
        for name in dirnames:
            path = Path(dirpath) / name
            key = (rel_dir / name).as_posix()
            if path.is_symlink():
                tree[key] = ("symlink", os.readlink(path))
            else:
                tree[key] = ("dir", None)
        for name in filenames:
            path = Path(dirpath) / name
            key = (rel_dir / name).as_posix()
            if path.is_symlink():
                tree[key] = ("symlink", os.readlink(path))
            else:
                tree[key] = ("file", path.read_bytes())
    return tree


def file_tree(root):
    """递归记录普通文件：相对路径 -> 字节。"""
    return {
        key: value[1]
        for key, value in snapshot_tree(root).items()
        if value[0] == "file"
    }


class RestoreValidationTests(unittest.TestCase):
    """无效快照必须在创建恢复目标之前被整体拒绝。"""

    def assertRejected(
        self, label, proc, dest, reason, snap_before, snapshot,
        work_before=None, work=None,
    ):
        stdout = proc.stdout.decode("utf-8", errors="replace")
        stderr = proc.stderr.decode("utf-8", errors="replace")
        context = (
            f"用例: {label}\n"
            f"exit={proc.returncode}\nstdout={stdout!r}\nstderr={stderr!r}"
        )

        self.assertEqual(proc.returncode, 2, f"退出码应为 2\n{context}")
        self.assertIn(ERROR_PREFIX, stderr, f"标准错误缺少错误提示\n{context}")
        self.assertIn(reason, stderr, f"标准错误缺少拒绝原因“{reason}”\n{context}")
        for marker in SUMMARY_MARKERS:
            self.assertNotIn(marker, stdout, f"标准输出出现了成功摘要\n{context}")
        self.assertFalse(
            os.path.lexists(dest),
            f"失败后恢复目标仍被创建: {dest}\n{context}",
        )
        self.assertEqual(
            snapshot_tree(snapshot), snap_before,
            f"调用前后快照目录内容发生变化\n{context}",
        )
        if work is not None:
            # 路径越界用例：快照之外的标记文件字节不变，且没有任何越界文件生成。
            self.assertEqual(
                snapshot_tree(work), work_before,
                f"失败后临时工作区出现新增或改动（可能发生越界写入）\n{context}",
            )

    def _reject_case(self, label, reason, mutate, dest_subdir=None,
                     traversal=False):
        """运行单个拒绝用例的通用流程，每种用例只引入一种无效条件。"""
        with tempfile.TemporaryDirectory(prefix="restore-test-") as work:
            snapshot = build_snapshot(work, {GOOD_FILE: GOOD_BYTES})

            # 恢复目标父目录可预先存在，但恢复目标本身必须事先不存在。
            if dest_subdir is not None:
                area = Path(work) / dest_subdir
                area.mkdir(parents=True, exist_ok=True)
                dest = area / "restored"
            else:
                dest = Path(work) / "restored"
            self.assertFalse(os.path.lexists(dest))

            # 每种用例只在此处引入唯一的无效条件（含快照外标记文件）。
            mutate(Path(work), snapshot)

            # 基线在夹具全部就绪后、调用 restore 前拍摄。
            snap_before = snapshot_tree(snapshot)
            work_before = snapshot_tree(work) if traversal else None

            proc = run_cmd(["restore", str(snapshot), str(dest)])
            self.assertRejected(
                label, proc, dest, reason, snap_before, snapshot,
                work_before=work_before, work=work if traversal else None,
            )

    # ---- 正常对照 ----

    def test_valid_v1_snapshot_restores_successfully(self):
        """版本1快照（含零字节二进制文件与嵌套中文路径）恢复成功。"""
        with tempfile.TemporaryDirectory(prefix="restore-test-") as work:
            snapshot = build_snapshot(work, VALID_FILES)
            dest = Path(work) / "restored"

            proc = run_cmd(["restore", str(snapshot), str(dest)])
            stdout = proc.stdout.decode("utf-8")
            stderr = proc.stderr.decode("utf-8")

            self.assertEqual(
                proc.returncode, 0,
                f"正常对照应返回 0\nstdout={stdout!r}\nstderr={stderr!r}",
            )
            self.assertEqual(stderr, "", f"成功时标准错误应为空\n{stderr!r}")
            self.assertIn(
                str(dest.resolve()), stdout,
                f"标准输出应包含恢复目标绝对路径\nstdout={stdout!r}",
            )
            self.assertIn(
                "已恢复文件数: 2", stdout,
                f"标准输出应包含文件数 2\nstdout={stdout!r}",
            )

            expected = file_tree(snapshot / "data")
            restored = file_tree(dest)
            self.assertEqual(
                set(restored), set(expected),
                "恢复后的相对路径集合与快照不一致",
            )
            for rel, data in expected.items():
                self.assertEqual(
                    restored[rel], data,
                    f"文件字节与快照不一致: {rel}",
                )
            # 显式固定公开语义：嵌套路径与含零字节的二进制文件逐字节保留。
            self.assertEqual(
                (dest / "note.txt").read_bytes(), VALID_FILES["note.txt"]
            )
            bin_bytes = (dest / "嵌套 目录" / "二进制 文件.bin").read_bytes()
            self.assertEqual(bin_bytes, VALID_FILES["嵌套 目录/二进制 文件.bin"])
            self.assertIn(0, bin_bytes)

