        traversal_rel = "../../marker.bin"

        def mutate(work, snapshot):
            marker = work / "marker.bin"
            marker.write_bytes(b"outside snapshot, do not touch\n")
            write_manifest(
                snapshot,
                {
                    "version": 1,
                    "files": [
                        {"path": GOOD_FILE},
                        {"path": traversal_rel},
                    ],
                },
            )

        self._reject_case(
            "包含 .. 分量的路径", "上级目录", mutate,
            dest_subdir="restore_area", traversal=True,
        )

